"use strict";const t=require("../common/vendor.js");exports.load=function(e,n){try{const r=t.index.getStorageSync(e);if(""!==r&&null!=r)return Array.isArray(r)?r.length>0?r:n:"object"==typeof r?Object.keys(r).length>0?r:n:r}catch{}return JSON.parse(JSON.stringify(n))},exports.save=function(e,n){try{t.index.setStorageSync(e,JSON.parse(JSON.stringify(n)))}catch{t.index.showToast({title:"存储失败",icon:"none"})}};
